#!/usr/bin/env bash
set -uo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"; FAIL=0
for x in node npm python3 cargo go java mvn gradle dotnet cmake swift dart composer bundle; do command -v "$x" >/dev/null 2>&1 || echo "[deps] missing tool: $x"; done
while IFS= read -r -d '' f; do d="$(dirname "$f")"; case "$(basename "$f")" in package.json) (cd "$d"; [[ -f package-lock.json || -f npm-shrinkwrap.json ]] && npm ci || npm install) || FAIL=$((FAIL+1));; requirements.txt) (cd "$d"; python3 -m pip install -r requirements.txt) || FAIL=$((FAIL+1));; pyproject.toml) (cd "$d"; python3 -m pip install -e .) || FAIL=$((FAIL+1));; Cargo.toml) (cd "$d"; cargo fetch) || FAIL=$((FAIL+1));; go.mod) (cd "$d"; go mod download) || FAIL=$((FAIL+1));; pom.xml) (cd "$d"; [[ -x mvnw ]] && ./mvnw -B dependency:go-offline || mvn -B dependency:go-offline) || FAIL=$((FAIL+1));; Package.swift) (cd "$d"; swift package resolve) || FAIL=$((FAIL+1));; pubspec.yaml) (cd "$d"; dart pub get) || FAIL=$((FAIL+1));; composer.json) (cd "$d"; composer install --no-interaction --prefer-dist) || FAIL=$((FAIL+1));; Gemfile) (cd "$d"; bundle install) || FAIL=$((FAIL+1));; esac; done < <(find "$ROOT" -type f \( -name package.json -o -name requirements.txt -o -name pyproject.toml -o -name Cargo.toml -o -name go.mod -o -name pom.xml -o -name Package.swift -o -name pubspec.yaml -o -name composer.json -o -name Gemfile \) -not -path '*/node_modules/*' -not -path '*/target/*' -not -path '*/build/*' -not -path '*/.git/*' -print0)
echo "Dependency bootstrap complete; failures=$FAIL"; exit "$FAIL"
